def table(rows):
 if not rows:return ''
 return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+esc(c)+'</th>' for c in rows[0])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(c)+'</td>' for c in r)+'</tr>' for r in rows[1:])+'</tbody></table></div>'
def diagram(b):
 if b.get('rows'):
  columns=b.get('columns',['Stage','Evidence','Result']);rows=b['rows'];grid='70px minmax(0,1fr)' if columns==['Step','Evidence and reasoning'] else 'repeat('+str(len(columns))+',minmax(0,1fr))';cells=''.join('<div class="diagram-row" style="grid-template-columns:'+grid+'">'+''.join('<div class="diagram-cell"><small>'+esc(columns[i])+'</small>'+esc(c)+'</div>' for i,c in enumerate(r))+'</div>' for r in rows)
 elif b.get('values'):
  cells='<p>'+esc(b.get('key',''))+'</p><div class="matrix">'+''.join('<div class="matrix-row">'+''.join('<span class="matrix-cell">'+esc(v)+'</span>' for v in r)+'</div>' for r in b['values'])+'</div>'
 elif b.get('series'):cells=table([['Series']+list(map(str,b['xValues']))]+[[s['label']]+list(map(str,s['values'])) for s in b['series']])
 else:cells='<p>'+esc(b.get('caption',''))+'</p>'
 return '<figure class="diagram"><h3>'+esc(b.get('title','Trace the evidence'))+'</h3>'+cells+'<figcaption>'+esc(b.get('caption',''))+'</figcaption></figure>'
def block(b):
 t=b['type'];text=b.get('text','')
 if t=='image':
  id=b['src'].split('/')[-1];width=min(b.get('width',600)*2,700)
  picture='<figure'+(' class="academy-picture"' if b.get('academy_visual') else '')+'><a href="../assets/'+id+'.png"><img loading="eager" src="../assets/'+id+'.png" alt="'+esc(b.get('alt','Concept illustration'))+'" style="width:'+str(width)+'px"/></a>'
  if b.get('academy_visual'):picture+='<figcaption>Follow the labelled picture with the matching explanation. <a href="../assets/'+id+'.svg">Open the vector diagram</a></figcaption>'
  return picture+'</figure>'
 if t=='gallery':return '<div class="gallery">'+''.join(''.join(block(x) for x in c) for c in b['cells'])+'</div>'
 if t=='diagram':return diagram(b)
 if t=='table':return table(b['rows'])
 if t=='code':return '<pre class="code"><code>'+esc(text)+'</code></pre>'
 if t=='response':return '<div class="response"><label>'+esc(b.get('label',text or 'My reasoning'))+'<textarea rows="'+str(min(b.get('lines',5),8))+'" aria-label="'+esc(b.get('label','My reasoning and evidence'))+'"></textarea><div class="print-answer"></div></label></div>'
 if t=='sensor':return '<div class="sensor" data-sensor><h3>The sensor measures. The rule decides.</h3><p>This model uses a made-up light scale, from 0 (darker) to 100 (brighter).</p><label>Light reading: <output>18</output><input type="range" min="0" max="100" step="1" value="18" aria-label="Light reading"/></label><p>Rule: if reading is below 30, turn the lamp on; otherwise turn it off.</p><p data-action>Lamp ON</p><p>Try 29, then 30. Which part measured the light, and which part chose the action?</p></div>'
 if t in ['heading','title','subheading']:return '<h3'+(' id="'+esc(b['anchor'])+'"' if b.get('anchor') else '')+'>'+esc(text)+'</h3>'
 if t=='callout':return '<aside class="note">'+esc(text)+'</aside>'
 return '<p>'+esc(text)+'</p>'
def filename(w):return ('bridge-' if w['id'].startswith('python') else f"ai-{w['level']}-")+f"week-{w['week']:02}.html"
def shell(title,body,base='../'):
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+'</title><link rel="stylesheet" href="'+base+'assets/programme.css"></head><body>'+body+'<script src="'+base+'assets/programme.js"></script><script src="'+base+'assets/learning-tools.js"></script></body></html>'
learning=json.loads((ROOT/'content/learning-tools.json').read_text()) if (ROOT/'content/learning-tools.json').exists() else {}
manifest=[]
for w in D['weeks']+D['python_bridge']:
 for role,key in [('student','sections'),('teacher','teacher'),('workbook','workbook')]:
  sections=w[key];name=filename(w);kind={'student':'Student lesson','teacher':'Teacher guide','workbook':'Workbook'}[role]
  links='<a href="index.html">All levels and weeks</a>'
  if role=='student':links+='<a href="../workbook/'+name+'">Matching workbook</a>'
  if role=='teacher':links+='<a href="../student/'+name+'">Student lesson</a><a href="../workbook/'+name+'">Workbook</a>'
  links+='<a href="../downloads/'+role+'/'+name.replace('.html','.docx')+'">Word edition</a><a href="../downloads/'+role+'/'+name.replace('.html','.pdf')+'">PDF edition</a><button onclick="window.print()">Print my copy</button>'
  contents='<nav class="contents" aria-label="Lesson contents">'+''.join(f'<a href="#section-{i+1}"><span>{i+1:02}</span>{esc(s["title"])}</a>' for i,s in enumerate(sections))+'</nav>'
  body='<main data-audience="'+role+'" data-week="'+w['id']+'"><header class="hero"><p class="kicker">AI Academy · '+('Python readiness bridge' if w['id'].startswith('python') else f"Level {w['level']} · Grade {w['grade']} · Week {w['week']}")+' · '+kind+'</p><h1>'+esc(w['title'])+'</h1><p>'+esc(D['purpose'])+'</p><p>Project: '+esc(w['project'])+'</p></header><div class="actions">'+links+'</div>'+contents
  if role=='student':body+='<section class="chapter"><h2>Before you start</h2><p>'+esc(w['recall'])+'</p><p>Plan time to read, investigate and explain. Keep predictions separate from observations.</p></section>'
  body+=''.join('<section class="chapter '+('teacher' if role=='teacher' else '')+'" id="section-'+str(i+1)+'" data-section="'+str(i+1)+'"><p class="kicker">'+kind+' · '+str(i+1)+' of '+str(len(sections))+'</p><h2>'+esc(s['title'])+'</h2>'+''.join(block(b) for b in s['blocks'])+'</section>' for i,s in enumerate(sections))
  if w['id'] in learning:body+='<script id="learning-tools-data" type="application/json">'+json.dumps(learning[w['id']],ensure_ascii=False).replace('<','\\u003c')+'</script>'
  body+='<footer>Save or print your responses for your portfolio. Progress and drafts on the hosted website stay in the current browser. Use only fictional or teacher-approved data.</footer></main>'
  dest=ROOT/role/name;dest.write_text(shell(w['title']+' · '+kind,body));manifest.append({'week':w['id'],'role':role,'file':f'{role}/{name}','sections':len(sections),'sha256':hashlib.sha256(dest.read_bytes()).hexdigest()})
for role in ['student','teacher','workbook']:
 guide='TEACHING_METHOD.html' if role=='teacher' else 'student/LEARNING_GUIDE.html'
 content='<main><p class="screen-only"><a href="../START_HERE.html">Programme home</a> · <a href="../'+guide+'">How to use the programme</a></p><header class="hero"><p class="kicker">AI Academy · '+role.title()+'</p><h1>A complete AI learning journey</h1><p>'+esc(D['purpose'])+'</p><p>Seven levels · 36 weeks each · Projects, investigations and independent evidence</p><p>'+esc(D['pacing'])+'</p></header><nav class="contents">'+''.join(f'<a href="#level-{l["number"]}">Level {l["number"]}: {esc(l["name"])}</a>'+('<a href="#bridge">Python Readiness Bridge</a>' if l['number']==3 else '') for l in D['levels'])+'</nav>'
 bridge='<section id="bridge" class="chapter"><h2>Python Readiness Bridge</h2><p>After Level 3 and before Level 4. Complete these twelve lessons unless you independently demonstrate equivalent Python skills.</p><div class="week-grid">'+''.join(f'<article class="week-card"><h3><a href="{filename(w)}">{w["week"]}. {esc(w["title"])}</a></h3></article>' for w in D['python_bridge'])+'</div></section>'
 for level in D['levels']:
  content+=f'<section id="level-{level["number"]}" class="chapter"><h2>Level {level["number"]}: {esc(level["name"])}</h2><p><strong>Typical grade:</strong> {level["grade"]}. Readiness determines placement.</p><p><strong>Before starting:</strong> {esc(level["prerequisites"])}</p><p><strong>Project:</strong> {esc(level["project"])}</p><div class="week-grid">'
  for w in D['weeks']:
   if w['level']==level['number']:content+=f'<article class="week-card"><p class="kicker">Week {w["week"]:02}</p><h3><a href="{filename(w)}">{esc(w["title"])}</a></h3><p>{len(w[{"student":"sections","teacher":"teacher","workbook":"workbook"}[role]])} connected sections</p></article>'
  content+='</div></section>'
  if level['number']==3:content+=bridge
 content+='</main>'
 (ROOT/role/'index.html').write_text(shell(role.title()+' · AI Academy',content))
home='<main><header class="hero"><p class="kicker">AI Academy · Complete Learning Programme</p><h1>Understand AI. Build thoughtfully. Explain your evidence.</h1><p>A complete programme for children and their teachers, from foundations to responsible AI research.</p><p>252 weekly lessons, matched teacher guides and workbooks, plus a Python readiness bridge.</p></header><div class="audience"><section class="chapter"><h2>Learn and investigate</h2><p>Read the explanation, follow the visual examples, test a changed case and add evidence to your project.</p><div class="actions"><a href="student/index.html">Open student lessons</a><a href="workbook/index.html">Open workbooks</a></div></section><section class="chapter"><h2>Prepare and teach</h2><p>Find the lesson purpose, board explanation, activities, answer reasoning, misconceptions and independent assessment.</p><div class="actions"><a href="teacher/index.html">Open teacher guides</a></div></section></div><section class="chapter"><h2>The learning journey</h2><p><a href="PROGRAMME_GUIDE.html">Read the programme and project guide</a> · <a href="TEACHING_METHOD.html">Teaching method</a> · <a href="student/LEARNING_GUIDE.html">Learning guide</a> · <a href="PICTORIAL_LESSONS.html">Explore the pictorial lessons</a></p><div class="levels">'+''.join(f'<div class="level-card"><p class="kicker">Level {l["number"]} · Typical Grade {l["grade"]}</p><h3>{esc(l["name"])}</h3><p>{esc(l["project"])}</p></div>'+('<div class="level-card"><p class="kicker">Preparation · 12 lessons</p><h3>Python Readiness Bridge</h3><p>After Level 3, prepare for Level 4. Independently demonstrate equivalent skills before skipping.</p></div>' if l['number']==3 else '') for l in D['levels'])+'</div></section></main>'
(ROOT/'START_HERE.html').write_text(shell('AI Academy · Start here',home,''));(ROOT/'index.html').write_text(shell('AI Academy · Start here',home,''));(ROOT/'reports/html-manifest.json').write_text(json.dumps(manifest,indent=2));print('Rendered',len(manifest),'audience resources and four navigation pages')
